import { requireTenantPermission } from './tenant.js';
import { appendAuditLedger } from './audit.js';
import { ensureFinanceSchema } from './finance-schema.js';
import { ensureFinanceAdvancedSchema } from './finance-advanced-schema.js';
import { ATLAS_VERSION } from './version.js';

const json=(body,status=200)=>Response.json(body,{status,headers:{'cache-control':'no-store','x-content-type-options':'nosniff'}});
const html=(body,status=200)=>new Response(body,{status,headers:{
  'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff',
  'referrer-policy':'strict-origin-when-cross-origin','permissions-policy':'camera=(), microphone=(), geolocation=()',
  'content-security-policy':"default-src 'self'; img-src 'self' data:; style-src 'unsafe-inline'; script-src 'unsafe-inline' 'self'; connect-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'"
}});

function text(value,max=240){return String(value??'').trim().replace(/\s+/g,' ').slice(0,max)}
function nullableText(value,max=500){const v=text(value,max);return v||null}
function isoDate(value){const v=text(value,10);return /^\d{4}-\d{2}-\d{2}$/.test(v)?v:null}
function safeInt(value,{min=Number.MIN_SAFE_INTEGER,max=Number.MAX_SAFE_INTEGER}={}){const n=Number(value);return Number.isSafeInteger(n)&&n>=min&&n<=max?n:null}
function safeLimit(url,fallback=50,max=100){const n=Number(url.searchParams.get('limit')||fallback);return Number.isFinite(n)?Math.max(1,Math.min(max,Math.trunc(n))):fallback}
async function bodyJson(request,maxBytes=131072){const raw=await request.text();if(raw.length>maxBytes)return{ok:false,status:413,error:'payload_too_large'};if(!raw.trim())return{ok:true,body:{}};try{return{ok:true,body:JSON.parse(raw)}}catch{return{ok:false,status:400,error:'invalid_json'}}}

async function authorize(request,env,permission,action){
  const authz=await requireTenantPermission(request,env,permission,action);
  if(!authz.ok)return{response:json({ok:false,error:authz.error},authz.status)};
  try{
    const base=await ensureFinanceSchema(env); if(!base.ok)return{response:json({ok:false,error:base.error},503)};
    const advanced=await ensureFinanceAdvancedSchema(env); if(!advanced.ok)return{response:json({ok:false,error:advanced.error},503)};
  }catch{return{response:json({ok:false,error:'finance_controls_schema_unavailable'},503)}}
  return{authz};
}
async function auditMutation(env,authz,action,resourceType,resourceId,metadata=null){
  try{
    await appendAuditLedger(env,{organizationId:authz.organizationId,dbaId:authz.dbaId,actorUserId:authz.session.user_id,category:'finance',action,resourceType,resourceId,decision:'allow',severity:'info',correlationId:authz.correlationId,metadata});
    return true;
  }catch{return false}
}
async function accountInScope(env,authz,accountId){
  return env.DB.prepare("SELECT id,account_type FROM finance_accounts WHERE id=? AND organization_id=? AND dba_id=? AND status='active'").bind(accountId,authz.organizationId,authz.dbaId).first();
}
async function journalInScope(env,authz,journalId){
  return env.DB.prepare("SELECT id FROM finance_journal_entries WHERE id=? AND organization_id=? AND dba_id=? AND status='posted'").bind(journalId,authz.organizationId,authz.dbaId).first();
}
async function bankInScope(env,authz,bankId){
  return env.DB.prepare("SELECT * FROM finance_bank_accounts WHERE id=? AND organization_id=? AND dba_id=?").bind(bankId,authz.organizationId,authz.dbaId).first();
}

async function listBankAccounts(request,env){
  const gate=await authorize(request,env,'module.read','finance.banking.read');if(gate.response)return gate.response;const{authz}=gate;
  const rows=await env.DB.prepare(`SELECT b.id,b.name,b.institution,b.account_last4,b.currency,b.ledger_account_id,b.opening_balance_cents,b.status,
    COALESCE(SUM(CASE WHEN t.status='posted' THEN t.amount_cents ELSE 0 END),0) AS transaction_total_cents
    FROM finance_bank_accounts b LEFT JOIN finance_bank_transactions t ON t.bank_account_id=b.id
    WHERE b.organization_id=? AND b.dba_id=?
    GROUP BY b.id ORDER BY b.status DESC,b.name`).bind(authz.organizationId,authz.dbaId).all();
  return json({ok:true,bankAccounts:(rows.results||[]).map(r=>({...r,current_balance_cents:Number(r.opening_balance_cents||0)+Number(r.transaction_total_cents||0)}))});
}
async function createBankAccount(request,env){
  const gate=await authorize(request,env,'module.write','finance.bank_account.create');if(gate.response)return gate.response;const{authz}=gate;
  const parsed=await bodyJson(request);if(!parsed.ok)return json({ok:false,error:parsed.error},parsed.status);const b=parsed.body;
  const name=text(b.name,160),institution=nullableText(b.institution,160),last4=text(b.accountLast4,4),currency=text(b.currency||'USD',3).toUpperCase(),ledgerAccountId=text(b.ledgerAccountId,128),opening=safeInt(b.openingBalanceCents??0);
  if(name.length<2||!ledgerAccountId||!/^[A-Z]{3}$/.test(currency)||(last4&&!/^\d{1,4}$/.test(last4))||opening==null)return json({ok:false,error:'valid_bank_account_fields_required'},400);
  const ledger=await accountInScope(env,authz,ledgerAccountId);if(!ledger||ledger.account_type!=='asset')return json({ok:false,error:'active_asset_ledger_account_required'},400);
  const id=crypto.randomUUID();await env.DB.prepare(`INSERT INTO finance_bank_accounts(id,organization_id,dba_id,name,institution,account_last4,currency,ledger_account_id,opening_balance_cents,status,created_by_user_id)
    VALUES(?,?,?,?,?,?,?,?,?,'active',?)`).bind(id,authz.organizationId,authz.dbaId,name,institution,last4||null,currency,ledgerAccountId,opening,authz.session.user_id).run();
  const auditRecorded=await auditMutation(env,authz,'finance.bank_account.create','finance_bank_account',id,{name,currency,ledgerAccountId});
  return json({ok:true,bankAccount:{id,name,institution,accountLast4:last4||null,currency,ledgerAccountId,openingBalanceCents:opening,status:'active'},auditRecorded},201);
}
async function listBankTransactions(request,env,url){
  const gate=await authorize(request,env,'module.read','finance.bank_transactions.read');if(gate.response)return gate.response;const{authz}=gate,limit=safeLimit(url);
  const bankId=text(url.searchParams.get('bankAccountId'),128);const clauses=['t.organization_id=?','t.dba_id=?'],binds=[authz.organizationId,authz.dbaId];if(bankId){clauses.push('t.bank_account_id=?');binds.push(bankId)}binds.push(limit);
  const rows=await env.DB.prepare(`SELECT t.id,t.bank_account_id,b.name AS bank_name,t.transaction_date,t.description,t.amount_cents,t.reference,t.journal_entry_id,t.status,t.reconciliation_id,t.created_at
    FROM finance_bank_transactions t JOIN finance_bank_accounts b ON b.id=t.bank_account_id
    WHERE ${clauses.join(' AND ')} ORDER BY t.transaction_date DESC,t.created_at DESC LIMIT ?`).bind(...binds).all();
  return json({ok:true,transactions:rows.results||[]});
}
async function createBankTransaction(request,env){
  const gate=await authorize(request,env,'module.write','finance.bank_transaction.create');if(gate.response)return gate.response;const{authz}=gate;
  const parsed=await bodyJson(request);if(!parsed.ok)return json({ok:false,error:parsed.error},parsed.status);const b=parsed.body;
  const bankAccountId=text(b.bankAccountId,128),date=isoDate(b.transactionDate)||new Date().toISOString().slice(0,10),description=text(b.description,300),amount=safeInt(b.amountCents),reference=nullableText(b.reference,120),journalEntryId=nullableText(b.journalEntryId,128),status=text(b.status||'posted',20);
  if(!bankAccountId||description.length<2||amount==null||amount===0||!['pending','posted'].includes(status))return json({ok:false,error:'valid_bank_transaction_fields_required'},400);
  const bank=await bankInScope(env,authz,bankAccountId);if(!bank||bank.status!=='active')return json({ok:false,error:'active_bank_account_required'},400);
  if(journalEntryId&&!await journalInScope(env,authz,journalEntryId))return json({ok:false,error:'journal_entry_not_found'},400);
  const id=crypto.randomUUID();await env.DB.prepare(`INSERT INTO finance_bank_transactions(id,organization_id,dba_id,bank_account_id,transaction_date,description,amount_cents,reference,journal_entry_id,status,created_by_user_id)
    VALUES(?,?,?,?,?,?,?,?,?,?,?)`).bind(id,authz.organizationId,authz.dbaId,bankAccountId,date,description,amount,reference,journalEntryId,status,authz.session.user_id).run();
  const auditRecorded=await auditMutation(env,authz,'finance.bank_transaction.create','finance_bank_transaction',id,{bankAccountId,amountCents:amount,journalEntryId,status});
  return json({ok:true,transaction:{id,bankAccountId,transactionDate:date,description,amountCents:amount,reference,journalEntryId,status},auditRecorded},201);
}

async function listReconciliations(request,env,url){
  const gate=await authorize(request,env,'module.read','finance.reconciliations.read');if(gate.response)return gate.response;const{authz}=gate,limit=safeLimit(url,30,100);
  const rows=await env.DB.prepare(`SELECT r.id,r.bank_account_id,b.name AS bank_name,r.statement_ending_date,r.statement_ending_balance_cents,r.calculated_balance_cents,r.difference_cents,r.status,r.completed_at,r.created_at
    FROM finance_reconciliations r JOIN finance_bank_accounts b ON b.id=r.bank_account_id
    WHERE r.organization_id=? AND r.dba_id=? ORDER BY r.statement_ending_date DESC,r.created_at DESC LIMIT ?`).bind(authz.organizationId,authz.dbaId,limit).all();
  return json({ok:true,reconciliations:rows.results||[]});
}
async function createReconciliation(request,env){
  const gate=await authorize(request,env,'module.write','finance.reconciliation.create');if(gate.response)return gate.response;const{authz}=gate;
  const parsed=await bodyJson(request);if(!parsed.ok)return json({ok:false,error:parsed.error},parsed.status);const b=parsed.body;
  const bankAccountId=text(b.bankAccountId,128),endingDate=isoDate(b.statementEndingDate),endingBalance=safeInt(b.statementEndingBalanceCents);
  if(!bankAccountId||!endingDate||endingBalance==null)return json({ok:false,error:'valid_reconciliation_fields_required'},400);
  const bank=await bankInScope(env,authz,bankAccountId);if(!bank)return json({ok:false,error:'bank_account_not_found'},404);
  const totals=await env.DB.prepare(`SELECT COALESCE(SUM(amount_cents),0) AS net,COALESCE(SUM(CASE WHEN journal_entry_id IS NULL AND status='posted' THEN 1 ELSE 0 END),0) AS unlinked
    FROM finance_bank_transactions WHERE organization_id=? AND dba_id=? AND bank_account_id=? AND transaction_date<=? AND status='posted'`).bind(authz.organizationId,authz.dbaId,bankAccountId,endingDate).first();
  const calculated=Number(bank.opening_balance_cents||0)+Number(totals?.net||0),difference=endingBalance-calculated,id=crypto.randomUUID();
  await env.DB.prepare(`INSERT INTO finance_reconciliations(id,organization_id,dba_id,bank_account_id,statement_ending_date,statement_ending_balance_cents,calculated_balance_cents,difference_cents,status,created_by_user_id)
    VALUES(?,?,?,?,?,?,?,?, 'draft',?)`).bind(id,authz.organizationId,authz.dbaId,bankAccountId,endingDate,endingBalance,calculated,difference,authz.session.user_id).run();
  const auditRecorded=await auditMutation(env,authz,'finance.reconciliation.create','finance_reconciliation',id,{bankAccountId,endingDate,differenceCents:difference,unlinkedToLedger:Number(totals?.unlinked||0)});
  return json({ok:true,reconciliation:{id,bankAccountId,statementEndingDate:endingDate,statementEndingBalanceCents:endingBalance,calculatedBalanceCents:calculated,differenceCents:difference,unlinkedToLedger:Number(totals?.unlinked||0),status:'draft'},auditRecorded},201);
}
async function completeReconciliation(request,env,id){
  const gate=await authorize(request,env,'module.write','finance.reconciliation.complete');if(gate.response)return gate.response;const{authz}=gate;
  const rec=await env.DB.prepare(`SELECT * FROM finance_reconciliations WHERE id=? AND organization_id=? AND dba_id=?`).bind(id,authz.organizationId,authz.dbaId).first();
  if(!rec)return json({ok:false,error:'reconciliation_not_found'},404);if(rec.status!=='draft')return json({ok:false,error:'reconciliation_not_draft'},409);
  const bank=await bankInScope(env,authz,rec.bank_account_id);if(!bank)return json({ok:false,error:'bank_account_not_found'},404);
  const totals=await env.DB.prepare(`SELECT COALESCE(SUM(amount_cents),0) AS net,COALESCE(SUM(CASE WHEN journal_entry_id IS NULL THEN 1 ELSE 0 END),0) AS unlinked
    FROM finance_bank_transactions WHERE organization_id=? AND dba_id=? AND bank_account_id=? AND transaction_date<=? AND status='posted'`).bind(authz.organizationId,authz.dbaId,rec.bank_account_id,rec.statement_ending_date).first();
  const calculated=Number(bank.opening_balance_cents||0)+Number(totals?.net||0),difference=Number(rec.statement_ending_balance_cents)-calculated,unlinked=Number(totals?.unlinked||0);
  if(difference!==0)return json({ok:false,error:'reconciliation_difference_not_zero',differenceCents:difference},409);
  if(unlinked!==0)return json({ok:false,error:'unlinked_bank_transactions_remain',unlinkedToLedger:unlinked},409);
  await env.DB.batch([
    env.DB.prepare(`UPDATE finance_reconciliations SET calculated_balance_cents=?,difference_cents=0,status='completed',completed_at=CURRENT_TIMESTAMP,completed_by_user_id=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(calculated,authz.session.user_id,id),
    env.DB.prepare(`UPDATE finance_bank_transactions SET reconciliation_id=?,updated_at=CURRENT_TIMESTAMP WHERE organization_id=? AND dba_id=? AND bank_account_id=? AND transaction_date<=? AND status='posted' AND reconciliation_id IS NULL`).bind(id,authz.organizationId,authz.dbaId,rec.bank_account_id,rec.statement_ending_date)
  ]);
  const auditRecorded=await auditMutation(env,authz,'finance.reconciliation.complete','finance_reconciliation',id,{bankAccountId:rec.bank_account_id,statementEndingDate:rec.statement_ending_date,calculatedBalanceCents:calculated});
  return json({ok:true,reconciliation:{id,status:'completed',differenceCents:0,calculatedBalanceCents:calculated},auditRecorded});
}

async function listBudgets(request,env){
  const gate=await authorize(request,env,'module.read','finance.budgets.read');if(gate.response)return gate.response;const{authz}=gate;
  const rows=await env.DB.prepare(`SELECT b.id,b.name,b.fiscal_year,b.status,COALESCE(SUM(l.amount_cents),0) AS total_cents,b.created_at
    FROM finance_budgets b LEFT JOIN finance_budget_lines l ON l.budget_id=b.id
    WHERE b.organization_id=? AND b.dba_id=? GROUP BY b.id ORDER BY b.fiscal_year DESC,b.name`).bind(authz.organizationId,authz.dbaId).all();
  return json({ok:true,budgets:rows.results||[]});
}
async function createBudget(request,env){
  const gate=await authorize(request,env,'module.write','finance.budget.create');if(gate.response)return gate.response;const{authz}=gate;
  const parsed=await bodyJson(request);if(!parsed.ok)return json({ok:false,error:parsed.error},parsed.status);const b=parsed.body,name=text(b.name,160),year=safeInt(b.fiscalYear,{min:2000,max:2200}),status=text(b.status||'draft',16);
  if(name.length<2||year==null||!['draft','active'].includes(status))return json({ok:false,error:'valid_budget_fields_required'},400);
  const id=crypto.randomUUID();try{await env.DB.prepare(`INSERT INTO finance_budgets(id,organization_id,dba_id,name,fiscal_year,status,created_by_user_id) VALUES(?,?,?,?,?,?,?)`).bind(id,authz.organizationId,authz.dbaId,name,year,status,authz.session.user_id).run()}catch{return json({ok:false,error:'budget_conflict'},409)}
  const auditRecorded=await auditMutation(env,authz,'finance.budget.create','finance_budget',id,{name,fiscalYear:year,status});return json({ok:true,budget:{id,name,fiscalYear:year,status},auditRecorded},201);
}
async function upsertBudgetLine(request,env,budgetId){
  const gate=await authorize(request,env,'module.write','finance.budget_line.upsert');if(gate.response)return gate.response;const{authz}=gate;
  const budget=await env.DB.prepare(`SELECT id FROM finance_budgets WHERE id=? AND organization_id=? AND dba_id=? AND status!='closed'`).bind(budgetId,authz.organizationId,authz.dbaId).first();if(!budget)return json({ok:false,error:'editable_budget_not_found'},404);
  const parsed=await bodyJson(request);if(!parsed.ok)return json({ok:false,error:parsed.error},parsed.status);const b=parsed.body,accountId=text(b.accountId,128),month=safeInt(b.periodMonth,{min:1,max:12}),amount=safeInt(b.amountCents,{min:0});
  if(!accountId||month==null||amount==null)return json({ok:false,error:'valid_budget_line_fields_required'},400);if(!await accountInScope(env,authz,accountId))return json({ok:false,error:'account_not_found'},404);
  const existing=await env.DB.prepare(`SELECT id FROM finance_budget_lines WHERE budget_id=? AND account_id=? AND period_month=?`).bind(budgetId,accountId,month).first();let id;
  if(existing){id=existing.id;await env.DB.prepare(`UPDATE finance_budget_lines SET amount_cents=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(amount,id).run()}else{id=crypto.randomUUID();await env.DB.prepare(`INSERT INTO finance_budget_lines(id,budget_id,account_id,period_month,amount_cents) VALUES(?,?,?,?,?)`).bind(id,budgetId,accountId,month,amount).run()}
  const auditRecorded=await auditMutation(env,authz,'finance.budget_line.upsert','finance_budget_line',id,{budgetId,accountId,periodMonth:month,amountCents:amount});return json({ok:true,budgetLine:{id,budgetId,accountId,periodMonth:month,amountCents:amount},auditRecorded});
}
