  const budget=await env.DB.prepare(`SELECT id,name,fiscal_year,status FROM finance_budgets WHERE id=? AND organization_id=? AND dba_id=?`).bind(budgetId,authz.organizationId,authz.dbaId).first();if(!budget)return json({ok:false,error:'budget_not_found'},404);
