export async function financeAdvancedRoutes(request,env,url=new URL(request.url)){
  const path=url.pathname.length>1?url.pathname.replace(/\/+$/,''):url.pathname;
  if(path==='/api/finance/bank-accounts'&&request.method==='GET')return listBankAccounts(request,env);
  if(path==='/api/finance/bank-accounts'&&request.method==='POST')return createBankAccount(request,env);
  if(path==='/api/finance/bank-transactions'&&request.method==='GET')return listBankTransactions(request,env,url);
  if(path==='/api/finance/bank-transactions'&&request.method==='POST')return createBankTransaction(request,env);
  if(path==='/api/finance/reconciliations'&&request.method==='GET')return listReconciliations(request,env,url);
  if(path==='/api/finance/reconciliations'&&request.method==='POST')return createReconciliation(request,env);
  const recComplete=path.match(/^\/api\/finance\/reconciliations\/([^/]+)\/complete$/);if(recComplete&&request.method==='POST')return completeReconciliation(request,env,decodeURIComponent(recComplete[1]));
  if(path==='/api/finance/budgets'&&request.method==='GET')return listBudgets(request,env);
  if(path==='/api/finance/budgets'&&request.method==='POST')return createBudget(request,env);
  const budget=path.match(/^\/api\/finance\/budgets\/([^/]+)$/);if(budget&&request.method==='GET')return budgetDetail(request,env,decodeURIComponent(budget[1]));
  const budgetLine=path.match(/^\/api\/finance\/budgets\/([^/]+)\/lines$/);if(budgetLine&&request.method==='POST')return upsertBudgetLine(request,env,decodeURIComponent(budgetLine[1]));
  if(path==='/api/finance/statements'&&request.method==='GET')return financialStatements(request,env,url);
  if(path==='/api/finance/taxes'&&request.method==='GET')return listTaxes(request,env);
  if(path==='/api/finance/taxes'&&request.method==='POST')return createTax(request,env);
  if(path==='/api/finance/fixed-assets'&&request.method==='GET')return listAssets(request,env,url);
  if(path==='/api/finance/fixed-assets'&&request.method==='POST')return createAsset(request,env);
  const ui=path.match(/^\/platform\/finance\/(banking|reconciliations|budgets|statements|taxes|fixed-assets)$/);if(ui&&request.method==='GET')return html(page(ui[1]));
  return null;
}
